-- Update t_scheme_details with scheme_category_id from t_scheme_masters
UPDATE t_scheme_details sd
SET scheme_category_id = sm.id
FROM tmp_scheme_category_map tmp
JOIN t_scheme_masters sm ON LOWER(TRIM(sm.name)) = LOWER(TRIM(tmp.scheme_category))
    AND sm.master_type = 'scheme_category'
    AND sm.is_active = true
WHERE sd.scheme_code = tmp.scheme_code
  AND sd.scheme_category_id IS NULL;

-- Show results
SELECT 
    CASE WHEN scheme_category_id IS NULL THEN 'Still NULL' ELSE 'Has Category' END as status,
    COUNT(*) as count
FROM t_scheme_details
GROUP BY 1;

-- Drop temp table
DROP TABLE tmp_scheme_category_map;

COMMIT;